begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','33000000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('33000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','join-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,8) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Private join project','UTC','GBP','2026-01-01',null,'team_project') id;
create temp table category as with c as (insert into public.project_areas(project_id,title) select id,'Secret Category' from ctx returning id) select * from c;
create temp table activity as select(public.create_activity_in_category((select id from ctx),(select id from category),'{"title":"Secret Activity","kind":"other","activity_type":"task"}',null)).id;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status,removed_at)
select ctx.id,('33000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Role fixture',
 case i when 2 then 'member' when 3 then 'viewer' else 'organizer' end::public.member_role,
 case i when 8 then 'removed' else 'active' end::public.member_status,case i when 8 then now() end from ctx,generate_series(2,3) i;
insert into storage.objects(bucket_id,name) select 'project-media',id::text||'/join-private-test.png' from ctx;
insert into storage.objects(bucket_id,name) select 'attachments',id::text||'/join-private-test.txt' from ctx;
-- A removed organizer and a second eligible organizer.
insert into public.project_members(project_id,user_id,display_name,role,status,removed_at)
select id,'33000000-0000-4000-8000-000000000008','Removed organizer','organizer','removed',now() from ctx;
select pg_temp.login(7);
create temp table other as select public.create_project('Other project','UTC','GBP','2026-01-01') id;
select pg_temp.login(1);
create temp table tokens as select public.regenerate_project_join_link((select id from ctx)) a;
select ok((select a ~ '^[0-9a-f]{64}$' from tokens),'256-bit token shape');
select is(public.get_project_join_access((select id from ctx))->>'token',(select a from tokens),'Organizer retrieves same current token');
select pg_temp.login(2);
select pg_temp.login(1);
select is(public.get_project_join_access((select id from ctx))->>'token',(select a from tokens),'Fresh authenticated claims recover unchanged token');
select is(public.resolve_project_join_link(public.get_project_join_access((select id from ctx))->>'token')->>'state','member','Recovered token resolves');
select is(public.resolve_project_join_link((select a from tokens))->>'state','member','Existing organizer is a member');
select is(public.request_project_access((select a from tokens))->>'state','member','Existing member does not request');
select ok(not exists(select 1 from public.projects p where p.id=(select id from ctx) and (to_jsonb(p)::text like '%'||(select a from tokens)||'%' or to_jsonb(p)::text ~ 'token_hash|token_ciphertext')),'Ordinary project rows contain no credential');
set local role postgres;
select is((select count(*)::int from app.project_join_requests where project_id=(select id from ctx)),0,'Member produced no request');
select is((select token_hash from app.project_join_links where project_id=(select id from ctx)),encode(extensions.digest((select a from tokens),'sha256'),'hex'),'SHA256 lookup hash stored');
select ok(not exists(select 1 from public.audit_log where project_id=(select id from ctx) and (coalesce(after::text,'') like '%'||(select a from tokens)||'%' or coalesce(after::text,'') like '%token_hash%')),'Audit contains neither token nor hash');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('app.project_join_links'::regclass,'app.project_join_requests'::regclass)),'Private join tables FORCE RLS');
select ok((select token_ciphertext is not null and position(convert_to((select a from tokens),'UTF8') in token_ciphertext)=0 from app.project_join_links where project_id=(select id from ctx)),'Token stored as ciphertext, not plaintext');
select ok(not exists(select 1 from public.audit_log where project_id=(select id from ctx) and (coalesce(before::text,'')||coalesce(after::text,'')) ~ 'token_hash|token_ciphertext'),'Audit excludes credential material');
select ok(not has_table_privilege('authenticated','vault.decrypted_secrets','SELECT') and not has_table_privilege('anon','vault.decrypted_secrets','SELECT'),'Clients cannot read Vault key');
select ok(not has_table_privilege('service_role','app.project_join_links','SELECT'),'Service role cannot read private ciphertext');
grant select on tokens,ctx to anon;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select public.get_project_join_access((select id from ctx))$$,'42501',null,'Anonymous cannot retrieve current token');
select is(public.resolve_project_join_link((select a from tokens)), '{"state":"sign_in"}'::jsonb,'Anonymous sees only safe state');
select is(public.resolve_project_join_link('bad'),'{"state":"unavailable"}'::jsonb,'Malformed token safe');
select is(public.resolve_project_join_link(repeat('f',64)),'{"state":"unavailable"}'::jsonb,'Unknown token safe');
select throws_ok($$select public.request_project_access((select a from tokens))$$,'42501',null,'Anonymous cannot request');
select throws_ok($$select * from public.projects where id=(select id from ctx)$$,'42501',null,'Anonymous cannot read project');
select throws_ok($$select * from public.commitments$$,'42501',null,'Anonymous cannot read activities');
select throws_ok($$select * from public.project_areas$$,'42501',null,'Anonymous cannot read categories');
select throws_ok($$select * from public.project_members$$,'42501',null,'Anonymous cannot read people');
select pg_temp.login(4);
select is(public.resolve_project_join_link((select a from tokens)),'{"state":"eligible"}'::jsonb,'Nonmember only sees eligible');
select is((select count(*)::int from public.projects where id=(select id from ctx)),0,'Token alone grants no project read');
select is(public.request_project_access((select a from tokens)),'{"state":"pending"}'::jsonb,'First request pending');
select is(public.request_project_access((select a from tokens)),'{"state":"pending"}'::jsonb,'Retry returns pending');
select is(public.resolve_project_join_link((select a from tokens)),'{"state":"pending"}'::jsonb,'Pending resolver exposes no project ID');
select throws_ok($$select * from app.project_join_links$$,'42501',null,'Client cannot read hashes');
select throws_ok($$insert into app.project_join_requests(project_id,join_link_id,requester_user_id) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Client cannot forge request');
select throws_ok($$update app.project_join_requests set status='approved'$$,'42501',null,'Client cannot approve directly');
select throws_ok($$select app.emit_domain_event('project.member_approved',(select id from ctx),gen_random_uuid(),'{}','approved')$$,'42501',null,'Client emitter denied');
select throws_ok($$select public.get_project_join_access((select id from ctx))$$,'42501',null,'Pending requester cannot retrieve current token');
select throws_ok($$select token_ciphertext from app.project_join_links$$,'42501',null,'Client cannot read encrypted token');
select ok(not app.is_member((select id from ctx)),'Pending request is not membership');
select throws_ok($$select * from public.get_project_health((select id from ctx))$$,'42501',null,'Pending requester cannot call health RPC');
select throws_ok($$select * from public.get_project_health_summary((select id from ctx))$$,'42501',null,'Pending requester cannot call health summary');
select is((select count(*)::int from public.get_project_timeline_events((select id from ctx),'2026-01-01','2027-01-01')),0,'Pending timeline RPC returns no data');
select throws_ok($$delete from app.project_join_links$$,'42501',null,'Client cannot delete links');
select throws_ok($$select app.require_join_organizer((select id from ctx),false)$$,'42501',null,'Internal authorization helper private');
select throws_ok($$select app.emit_domain_event('payment.confirmed',(select id from ctx),gen_random_uuid(),'{}','spoof')$$,'42501',null,'Future event spoofing denied');
-- Enumerate every normal public table/view with project_id, including financial/read models.
set local role postgres;
create temp table project_surfaces as select c.table_schema,c.table_name from information_schema.columns c where c.table_schema='public' and c.column_name='project_id';
grant select on project_surfaces to authenticated;
select pg_temp.login(4);
create function pg_temp.no_project_data() returns boolean language plpgsql as $$ declare r record;n bigint;begin
 for r in select * from project_surfaces loop
  begin execute format('select count(*) from %I.%I where project_id=$1',r.table_schema,r.table_name) into n using (select id from ctx);
  exception when insufficient_privilege then n:=0; end;
  if n<>0 then raise exception 'Pending requester can read %',r.table_name; end if;
 end loop;
 return true;
end $$;
select ok(pg_temp.no_project_data(),'Pending cannot read any project-scoped table/view: activities categories budget financials people notes timeline health payments shares balances findings notifications');
select is((select count(*)::int from public.projects where id=(select id from ctx)),0,'Pending cannot read project');
select is((select count(*)::int from storage.objects where name like (select id::text||'/%' from ctx)),0,'Pending cannot read project storage');
set local role postgres;
create temp table req as select id from app.project_join_requests where project_id=(select id from ctx);
grant select on req to authenticated;
select is((select count(*)::int from req),1,'One pending request');
select is((select count(*)::int from app.domain_events where project_id=(select id from ctx) and event_type='project.join_requested'),1,'One requested event');
select is((select count(*)::int from public.notifications where project_id=(select id from ctx) and kind='project_join_requested'),1,'Only active organizer notified once');
select is((select recipient_user_id from public.notifications where project_id=(select id from ctx) and kind='project_join_requested'),'33000000-0000-4000-8000-000000000001'::uuid,'Correct organizer recipient');
select throws_ok($$select app.emit_domain_event('project.join_requested',(select id from ctx),(select id from req),'{"profile":"bad"}','requested')$$,'22023',null,'Join payload validation');
select pg_temp.login(4);
select throws_ok($$select public.review_project_join_request((select id from req),true)$$,'42501',null,'Requester cannot self-approve');
select pg_temp.login(2);
select throws_ok($$select public.get_project_join_access((select id from ctx))$$,'42501',null,'Member cannot view queue');
select throws_ok($$select public.regenerate_project_join_link((select id from ctx))$$,'42501',null,'Member cannot regenerate');
select throws_ok($$select public.disable_project_join_link((select id from ctx))$$,'42501',null,'Member cannot disable');
select throws_ok($$select public.review_project_join_request((select id from req),true)$$,'42501',null,'Member cannot approve');
select throws_ok($$select public.review_project_join_request((select id from req),false)$$,'42501',null,'Member cannot decline');
select pg_temp.login(3);
select throws_ok($$select public.get_project_join_access((select id from ctx))$$,'42501',null,'Viewer cannot retrieve current token');
select throws_ok($$select public.review_project_join_request((select id from req),true)$$,'42501',null,'Viewer cannot approve');
select throws_ok($$select public.disable_project_join_link((select id from ctx))$$,'42501',null,'Viewer cannot manage link');
select pg_temp.login(7);
select throws_ok($$select public.get_project_join_access((select id from ctx))$$,'42501',null,'Cross-project organizer cannot retrieve current token');
select throws_ok($$select public.review_project_join_request((select id from req),true)$$,'42501',null,'Cross-project organizer cannot approve');
select pg_temp.login(1);
alter table tokens add column b text;
update tokens set b=public.regenerate_project_join_link((select id from ctx));
select is(public.resolve_project_join_link((select a from tokens))->>'state','unavailable','Regenerated old token invalid');
select isnt((select a from tokens),(select b from tokens),'Regeneration changes token');
select is(public.get_project_join_access((select id from ctx))->>'token',(select b from tokens),'Current retrieval returns regenerated token');
select is(public.resolve_project_join_link((select b from tokens))->>'state','member','New token valid');
select is((public.get_project_join_access((select id from ctx))->>'pending_count')::int,1,'Pending survives regeneration');
select public.disable_project_join_link((select id from ctx));
select is(public.get_project_join_access((select id from ctx))->>'token',null::text,'Disabled link returns no bearer credential');
select is(public.get_project_join_access((select id from ctx))->>'active','false','Disabled state returned');
select is(public.resolve_project_join_link((select b from tokens))->>'state','unavailable','Disabled token invalid');
select is((public.get_project_join_access((select id from ctx))->>'pending_count')::int,1,'Pending survives disabling');
select pg_temp.login(5);
select throws_ok($$select public.request_project_access((select b from tokens))$$,'P0001',null,'Disabled stale page cannot request');
select pg_temp.login(1);
select lives_ok($$select public.review_project_join_request((select id from req),true)$$,'Approve even after disable');
select lives_ok($$select public.review_project_join_request((select id from req),true)$$,'Repeated approve safe');
set local role postgres;
select is((select role::text from public.project_members where project_id=(select id from ctx) and user_id='33000000-0000-4000-8000-000000000004'),'member','Approval grants Member only');
select is((select status from app.project_join_requests where id=(select id from req)),'approved','Request reviewed');
select is((select count(*)::int from app.domain_events where resource_id=(select id from req) and event_type='project.member_approved'),1,'One approved event');
select is((select count(*)::int from public.notifications where join_request_id=(select id from req) and kind='project_member_approved'),1,'One approval notification');
select is((select recipient_user_id from public.notifications where join_request_id=(select id from req) and kind='project_member_approved'),'33000000-0000-4000-8000-000000000004'::uuid,'Correct approved recipient');
select pg_temp.login(4);
select is((select count(*)::int from public.v_my_projects where project_id=(select id from ctx)),1,'Approved project immediately visible');
select is((select count(*)::int from public.commitments where id=(select id from activity)),1,'Approved activity visible');
select is((select count(*)::int from public.v_my_join_notifications),1,'Requester inbox approval');
select public.mark_notification_read((select id from public.v_my_join_notifications limit 1));
select is((select count(*)::int from public.v_my_join_notifications where read_at is null),0,'Join notification read state');
select throws_ok($$select public.regenerate_project_join_link((select id from ctx))$$,'42501',null,'Approved user has no organizer privilege');
select pg_temp.login(1);
update tokens set b=public.regenerate_project_join_link((select id from ctx));
select pg_temp.login(5);
select public.request_project_access((select b from tokens));
set local role postgres;
create temp table declined as select id from app.project_join_requests where project_id=(select id from ctx) and requester_user_id='33000000-0000-4000-8000-000000000005';
grant select on declined to authenticated;
select pg_temp.login(1);
select public.review_project_join_request((select id from declined),false);
select lives_ok($$select public.review_project_join_request((select id from declined),false)$$,'Repeated decline safe');
select pg_temp.login(5);
select ok(not app.is_member((select id from ctx)),'Decline creates no membership');
select is((select count(*)::int from public.projects where id=(select id from ctx)),0,'Declined requester still isolated');
select is(public.resolve_project_join_link((select b from tokens))->>'state','eligible','Declined can request again');
select public.request_project_access((select b from tokens));
set local role postgres;
select is((select count(*)::int from app.project_join_requests where project_id=(select id from ctx) and requester_user_id='33000000-0000-4000-8000-000000000005'),2,'Re-request is a new historical request');
select is((select count(*)::int from app.domain_events where resource_id=(select id from declined) and event_type='project.member_approved'),0,'Decline emits no approval');
select pg_temp.login(8);
select public.request_project_access((select b from tokens));
set local role postgres;
create temp table removed_req as select id from app.project_join_requests where project_id=(select id from ctx) and requester_user_id='33000000-0000-4000-8000-000000000008';
grant select on removed_req to authenticated;
select pg_temp.login(1);
select public.review_project_join_request((select id from removed_req),true);
set local role postgres;
select is((select role::text from public.project_members where project_id=(select id from ctx) and user_id='33000000-0000-4000-8000-000000000008'),'member','Removed organizer rejoins as Member only');
select is((select count(*)::int from public.project_members where project_id=(select id from ctx) and user_id='33000000-0000-4000-8000-000000000008'),1,'Existing membership reactivated without duplicate');
select pg_temp.login(1);
-- A direct invitation accepted while a join request is pending wins without role changes.
select pg_temp.login(6);
select public.request_project_access((select b from tokens));
set local role postgres;
create temp table already_member_req as select id from app.project_join_requests where project_id=(select id from ctx) and requester_user_id='33000000-0000-4000-8000-000000000006';
grant select on already_member_req to authenticated;
select pg_temp.login(1);
select public.create_invitation((select id from ctx),'join-test-6@example.test','viewer');
select pg_temp.login(6);
select public.accept_invitation((select token from public.list_my_invitations() where project_id=(select id from ctx)));
select pg_temp.login(1);
select public.review_project_join_request((select id from already_member_req),true);
set local role postgres;
select is((select role::text from public.project_members where project_id=(select id from ctx) and user_id='33000000-0000-4000-8000-000000000006'),'viewer','Existing direct-invite role remains unchanged');
select is((select count(*)::int from app.domain_events where resource_id=(select id from already_member_req) and event_type='project.member_approved'),0,'Already active membership emits no approval fact');
select is((select count(*)::int from public.notifications where join_request_id=(select id from already_member_req) and kind='project_member_approved'),0,'No approval notification for unchanged membership');
select is((select count(*)::int from app.project_join_links where project_id=(select id from ctx) and revoked_at is null),1,'Exactly one active link after multiple regenerations');
select throws_ok($$insert into app.project_join_links(project_id,token_hash,created_by_user_id,token_ciphertext) select (select id from other),token_hash,'33000000-0000-4000-8000-000000000001',token_ciphertext from app.project_join_links where project_id=(select id from ctx) and revoked_at is null$$,'23505',null,'Token hash cannot resolve multiple links/projects');
select app.process_domain_event(id) from app.domain_events where resource_id=(select id from req);
select is((select count(*)::int from app.domain_event_processing p join app.domain_events e on e.id=p.event_id where e.resource_id=(select id from req)),2,'Both join facts have one processing receipt');
select is((select count(*)::int from app.automation_action_runs a join app.domain_events e on e.id=a.event_id where e.resource_id=(select id from req)),2,'Replay preserves exactly one receipt per action');
select is((select count(*)::int from public.notifications where join_request_id=(select id from req)),2,'Replaying requested and approved facts creates no duplicate notifications');
select pg_temp.login(1);
select throws_ok($$select public.review_project_join_request((select id from declined),true)$$,'P0001',null,'Declined request cannot later be approved');

update public.projects set status='archived' where id=(select id from ctx);
select is(public.resolve_project_join_link((select b from tokens))->>'state','unavailable','Archived project link unavailable');
select pg_temp.login(6);
select throws_ok($$select public.request_project_access((select b from tokens))$$,'P0001',null,'Archived project rejects request');
select pg_temp.login(1);
update public.projects set status='active' where id=(select id from ctx);
select public.soft_delete_project((select id from ctx));
select is(public.resolve_project_join_link((select b from tokens))->>'state','unavailable','Deleted project link unavailable');
select * from finish();
rollback;
